const items = $input.all();
const counts = $('Get Today Counts').first().json;

const LI_DAILY_CONNECT_CAP = Number($env.LI_DAILY_CONNECT_CAP);
const LI_DAILY_VISIT_CAP = Number($env.LI_DAILY_VISIT_CAP);
const EMAIL_DAILY_CAP_PER_INBOX = Number($env.EMAIL_DAILY_CAP_PER_INBOX);

let liConnectCount = Number(counts.li_connect_today);
let liVisitCount = Number(counts.li_visit_today);
let emailCount = Number(counts.email_today);

function fillTemplate(tpl, row) {
  if (!tpl) return tpl;
  return tpl
    .replace(/\{\{full_name\}\}/g, row.full_name || '')
    .replace(/\{\{company\}\}/g, row.company || '');
}

const out = [];
for (const item of items) {
  const row = item.json;

  if (row.action_type === 'li_connect') {
    if (liConnectCount >= LI_DAILY_CONNECT_CAP) continue;
    liConnectCount++;
    out.push({ json: {
      target: 'linkedin-dispatch',
      payload: {
        prospect_id: row.prospect_id,
        step_id: row.step_id,
        action_type: row.action_type,
        profile_url: row.linkedin_url,
        next_step_id: row.next_step_id,
      },
    } });
  } else if (row.action_type === 'li_visit') {
    if (liVisitCount >= LI_DAILY_VISIT_CAP) continue;
    liVisitCount++;
    out.push({ json: {
      target: 'linkedin-dispatch',
      payload: {
        prospect_id: row.prospect_id,
        step_id: row.step_id,
        action_type: row.action_type,
        profile_url: row.linkedin_url,
        next_step_id: row.next_step_id,
      },
    } });
  } else if (row.action_type === 'li_message' || row.action_type === 'li_invite') {
    const msg = fillTemplate(row.body_template, row);
    out.push({ json: {
      target: 'linkedin-dispatch',
      payload: {
        prospect_id: row.prospect_id,
        step_id: row.step_id,
        action_type: row.action_type,
        profile_url: row.linkedin_url,
        message: msg ? msg.replace(/<[^>]+>/g, '') : msg,
        next_step_id: row.next_step_id,
      },
    } });
  } else if (row.action_type === 'email' || row.action_type === 'email_followup') {
    if (emailCount >= EMAIL_DAILY_CAP_PER_INBOX) continue;
    emailCount++;
    out.push({ json: {
      target: 'email-send',
      payload: {
        prospect_id: row.prospect_id,
        step_id: row.step_id,
        to_email: row.email,
        to_name: row.full_name,
        subject: fillTemplate(row.subject, row),
        html_content: fillTemplate(row.body_template, row),
        next_step_id: row.next_step_id,
      },
    } });
  }
}
return out;
